const { segmentos } = $input.first().json;
const segmentosStr = segmentos.map(s => `'${s}'`).join(',');

const query = `SELECT id, categoria, segmento, titulo, contenido, activo FROM conocimiento_academia WHERE segmento IN (${segmentosStr}) AND activo = true ORDER BY categoria, segmento, titulo LIMIT 20`;

return [{ json: { query } }];

const rows = $input.all().map(i => i.json);
const normData = $('Mapear Segmentos2').first().json;

if (!rows || rows.length === 0) {
  return [{
    json: {
      contexto_encontrado: false,
      contexto: 'Sin contexto disponible.',
      pregunta: normData.pregunta,
      lead_tipo: normData.lead_tipo,
      items_encontrados: 0
    }
  }];
}

const contexto = rows
  .map(r => `**${r.categoria} (${r.segmento})**\n${r.titulo}\n${r.contenido}`)
  .join('\n\n');

return [{
  json: {
    contexto_encontrado: true,
    contexto,
    pregunta: normData.pregunta,
    lead_tipo: normData.lead_tipo,
    items_encontrados: rows.length
  }
}];

const { pregunta, lead_tipo } = $input.first().json;

const segmentosMap = {
  KIDS: ['KIDS', 'GENERAL'],
  ADOLESCENTE: ['KIDS', 'ADULTOS', 'GENERAL'],
  ADULTO: ['ADULTOS', 'PERSONALIZADO', 'GENERAL'],
  AU_PAIR: ['AU_PAIR', 'GENERAL'],
  GENERAL: ['GENERAL']
};

const segmentos = segmentosMap[lead_tipo] || segmentosMap['GENERAL'];

return [{
  json: {
    pregunta: pregunta || 'información general',
    lead_tipo: lead_tipo || 'GENERAL',
    segmentos
  }
}];

const synth = $input.first().json;
const procData = $('Procesar Resultados').first().json;

let respuesta = 'No tengo esa información disponible.';
if (synth?.choices?.[0]?.message?.content) {
  respuesta = synth.choices[0].message.content.trim();
}

return [{
  json: {
    resultado: respuesta,
    confianza: procData.contexto_encontrado ? 'ALTA' : 'BAJA',
    items_consultados: procData.items_encontrados
  }
}];

const { segmentos } = $input.first().json;
const segmentosStr = segmentos.map((s) => `'${String(s).replace(/'/g, "''")}'`).join(',');

const query = `SELECT id, categoria, segmento, titulo, contenido, activo FROM conocimiento_academia WHERE segmento IN (${segmentosStr}) AND activo = true ORDER BY segmento, categoria, titulo LIMIT 100`;

return [{ json: { query, type: 'conocimiento' } }];

const { pregunta, lead_tipo } = $input.first().json;

// lead_tipo -> segmentos de conocimiento_academia. Acepta singular/plural.
const segmentosMap = {
  KIDS: ['KIDS', 'GENERAL'],
  ADOLESCENTE: ['KIDS', 'ADULTOS', 'GENERAL'],
  'KIDS-ADOLESCENTES': ['KIDS', 'ADULTOS', 'GENERAL'],
  ADULTO: ['ADULTOS', 'PERSONALIZADO', 'GENERAL'],
  ADULTOS: ['ADULTOS', 'PERSONALIZADO', 'GENERAL'],
  PERSONALIZADO: ['PERSONALIZADO', 'GENERAL'],
  // Las clases de Au Pair son clases comunes: usan los precios de adultos / personalizadas
  AU_PAIR: ['AU_PAIR', 'ADULTOS', 'PERSONALIZADO', 'GENERAL'],
  GENERAL: ['GENERAL']
};

// Si lead_tipo viene vacío o desconocido, se busca en TODOS los segmentos.
const TODOS = ['KIDS', 'ADULTOS', 'PERSONALIZADO', 'AU_PAIR', 'GENERAL'];

const lt = (lead_tipo || '').toString().trim().toUpperCase();
const segmentos = segmentosMap[lt] || TODOS;

return [{
  json: {
    pregunta: pregunta || 'información general',
    lead_tipo: lead_tipo || 'GENERAL',
    segmentos
  }
}];

const items = $input.all();
const normData = $('Mapear Segmentos').first().json;

const lt = String(normData.lead_tipo || '').toUpperCase();
const esKids = ['KIDS', 'ADOLESCENTE', 'KIDS-ADOLESCENTES'].includes(lt);
const esAdulto = ['ADULTO', 'ADULTOS', 'PERSONALIZADO', 'AU_PAIR'].includes(lt);
// Cada segmento recibe solo SU link (evita mandar el de niños a un adulto)
const omitir = (clave) =>
  (esAdulto && ['link_propuesta_kids', 'instagram_kids', 'web_kids'].includes(clave)) ||
  (esKids && clave === 'link_propuesta_adultos');

let conocimiento = '';
let config = '';

items.forEach((item) => {
  const data = item.json;
  // Se distingue por la forma de los datos (el Postgres reemplaza el json del item)
  const esConocimiento = data.categoria !== undefined && data.contenido !== undefined;
  const esConfig = data.clave !== undefined && data.valor !== undefined;

  if (esConocimiento) {
    conocimiento += `- [${data.segmento} / ${data.categoria}] ${String(data.titulo || '').trim()}: ${String(data.contenido || '').trim()}\n`;
  } else if (esConfig) {
    if (!omitir(data.clave)) config += `- ${data.clave}: ${data.valor}\n`;
  }
});

let contexto = '';
if (conocimiento.trim()) contexto += 'INFORMACIÓN DE LA ACADEMIA (base de conocimiento):\n' + conocimiento;
if (config.trim()) contexto += '\nCONFIGURACIÓN (dirección, datos de pago y operativos):\n' + config;

return [{
  json: {
    contexto_encontrado: contexto.trim().length > 0,
    contexto: contexto.trim() || 'Sin información disponible.',
    pregunta: normData.pregunta,
    lead_tipo: normData.lead_tipo
  }
}];

const p = $('Procesar Contextos').first().json;

if (!p.contexto_encontrado) {
  return [{ json: {
    resultado: 'No hay información cargada para esta consulta. NO inventes nada: decile que lo consultás con Fla y avisale con solicitar-contacto-fla.',
    confianza: 'BAJA'
  } }];
}

const instruccion = [
  'Usá SOLO los DATOS OFICIALES de abajo para responder lo que preguntó la persona. NO los vuelques todos juntos: elegí lo que corresponde a su pregunta.',
  'Si el dato que piden no figura, NO lo inventes ni lo completes con suposiciones: decí que lo consultás con Fla y llamá a solicitar-contacto-fla.',
  'Precio: informá el valor de SU caso (grupal, personalizado, hermanos) con una línea de detalle. Hermanos: hacé la cuenta a la vista (cuota x cantidad, menos 10%, total final) con los valores de abajo. Escribí los montos con punto de miles, tal cual figuran.',
  'Propuesta: mandá el link que corresponde (link_propuesta_kids para niños, link_propuesta_adultos para adultos) con el texto estándar de Fla.',
  'Datos de pago: SOLO si preguntó cómo pagar o ya decidió inscribirse, y siempre junto con el monto de su caso. PRIMERO los de Mercado Pago (pago_mp_*); solo si no puede pagar por Mercado Pago, los del banco (pago_banco, pago_titular, pago_alias, pago_cbu). Ubicación: solo si preguntó dónde queda.',
  'Hablá con la voz de Fla: mensajes cortos, sin negritas ni viñetas con guiones, casi sin emojis y sin cerrar con "estoy acá para ayudarte".',
  'Links: pegá la URL sola, sin formato [texto](url). Usá únicamente el link de propuesta que figura abajo.',
  'Si es el primer mensaje de la conversación, empezá presentándote: "Hola! Soy Lucia, la asistente de Fla 💛".',
  'Nunca dejes textos entre corchetes sin completar.'
].join('\n');

return [{ json: {
  resultado: `${instruccion}\n\nPREGUNTA DEL CLIENTE: ${p.pregunta}\n\nDATOS OFICIALES:\n${p.contexto}`,
  confianza: 'ALTA'
} }];
